(()=>{const $=s=>document.querySelector(s),P=BoardPalette,fixtures=[7,10,12].map(n=>LEVELS.find(p=>p.n===n));function el(tag,text,cls){const node=document.createElement(tag);if(text)node.textContent=text;if(cls)node.className=cls;return node}function draw(){const mode=$('#vision').value,optimized=$('#optimize').checked,threshold=+$('#threshold').value,color=i=>P.simulate(P.V2[i],mode);$('#swatches').replaceChildren();P.V2.forEach((hex,i)=>{const box=el('div',null,'swatch'),chip=el('div',null,'color');chip.style.background=color(i);box.append(chip,el('p',String(i+1).padStart(2,'0')+' '+P.NAMES[i]+' '+hex));$('#swatches').append(box)});function pair(a,b,root){const box=el('div',null,'pair'),chips=el('div',null,'comparison');for(const id of [a,b]){const chip=el('span');chip.style.background=color(id);chips.append(chip)}box.append(chips,el('p',P.NAMES[a]+' / '+P.NAMES[b]+' · ΔE76 '+P.delta(P.V2[a],P.V2[b]).toFixed(1)));root.append(box)}$('#pairs').replaceChildren();[[1,9],[3,10],[0,11],[5,7],[2,9]].forEach(([a,b])=>pair(a,b,$('#pairs')));$('#all-pairs').replaceChildren();for(let a=0;a<12;a++)for(let b=a+1;b<12;b++)pair(a,b,$('#all-pairs'));$('#boards').replaceChildren();fixtures.forEach(p=>{const section=el('section',null,'fixture'),left=el('div'),info=el('div',null,'info');left.append(el('h2',p.n+' × '+p.n+' · 現有題目'));const board=el('div',null,'test-board');board.style.gridTemplateColumns=`repeat(${p.n},minmax(0,1fr))`;board.style.gridTemplateRows=`repeat(${p.n},minmax(0,1fr))`;const map=P.mapping(p,optimized);p.regions.forEach((id,i)=>{const cell=el('div',null,'test-cell');cell.style.background=color(map[id]);cell.title='色區 '+(id+1)+' · '+P.NAMES[map[id]];if(i%p.n<p.n-1&&p.regions[i+1]!==id)cell.classList.add('edge-r');if(i+p.n<p.n*p.n&&p.regions[i+p.n]!==id)cell.classList.add('edge-b');board.append(cell)});left.append(board);const audit=P.audit(p,optimized),before=P.audit(p,false);info.append(el('h3','相鄰辨識紀錄'),el('p',`最低 ΔE76：原配置 ${before[0].deltaE76} → 目前 ${audit[0].deltaE76}。標記值 ${threshold} 以下 ${audit.filter(v=>v.deltaE76<threshold).length} 組。`));const table=el('table'),head=el('tr');['相鄰色區','原色色差'].forEach(t=>head.append(el('th',t)));table.append(head);audit.slice(0,10).forEach(a=>{const row=el('tr');if(a.deltaE76<threshold)row.className='review';row.append(el('td',`${a.a+1} / ${a.b+1}`),el('td',String(a.deltaE76)));table.append(row)});info.append(table);section.append(left,info);$('#boards').append(section)})}['#vision','#optimize','#threshold'].forEach(s=>$(s).onchange=draw);draw()})();
